import java.util.*;

class Solution {
    private static final double TARGET = 24.0;
    private static final double EPS = 1e-6;

    public boolean judgePoint24(int[] cards) {
        List<Double> values = new ArrayList<>();
        for (int card : cards) {
            values.add((double) card);
        }
        return canReach(values);
    }

    private boolean canReach(List<Double> values) {
        if (values.size() == 1) {
            return Math.abs(values.get(0) - TARGET) < EPS;
        }
        int n = values.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                List<Double> rest = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        rest.add(values.get(k));
                    }
                }
                double a = values.get(i);
                double b = values.get(j);
                for (double nextValue : combineAll(a, b)) {
                    rest.add(nextValue);
                    if (canReach(rest)) {
                        return true;
                    }
                    rest.remove(rest.size() - 1);
                }
            }
        }
        return false;
    }

    private List<Double> combineAll(double a, double b) {
        List<Double> results = new ArrayList<>();
        results.add(a + b);
        results.add(a - b);
        results.add(b - a);
        results.add(a * b);
        if (Math.abs(b) > EPS) {
            results.add(a / b);
        }
        if (Math.abs(a) > EPS) {
            results.add(b / a);
        }
        return results;
    }
}

