class Solution {
    private static final double TARGET = 24.0;
    private static final double EPS = 1e-6;

    public boolean judgePoint24(int[] cards) {
        double[] ordered = new double[4];
        boolean[] used = new boolean[4];
        return permute(cards, used, ordered, 0);
    }

    private boolean permute(int[] cards, boolean[] used, double[] ordered, int depth) {
        if (depth == 4) {
            return evaluateFiveShapes(ordered[0], ordered[1], ordered[2], ordered[3]);
        }
        for (int i = 0; i < cards.length; i++) {
            if (used[i]) {
                continue;
            }
            used[i] = true;
            ordered[depth] = cards[i];
            if (permute(cards, used, ordered, depth + 1)) {
                return true;
            }
            used[i] = false;
        }
        return false;
    }

    private boolean evaluateFiveShapes(double a, double b, double c, double d) {
        for (double ab : results(a, b)) {
            for (double abc : results(ab, c)) {
                if (anyEquals24(results(abc, d))) {
                    return true;
                }
            }
            for (double cd : results(c, d)) {
                if (anyEquals24(results(ab, cd))) {
                    return true;
                }
            }
        }
        for (double bc : results(b, c)) {
            for (double abc : results(a, bc)) {
                if (anyEquals24(results(abc, d))) {
                    return true;
                }
            }
            for (double bcd : results(bc, d)) {
                if (anyEquals24(results(a, bcd))) {
                    return true;
                }
            }
        }
        for (double cd : results(c, d)) {
            for (double bcd : results(b, cd)) {
                if (anyEquals24(results(a, bcd))) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean anyEquals24(List<Double> values) {
        for (double value : values) {
            if (Math.abs(value - TARGET) < EPS) {
                return true;
            }
        }
        return false;
    }

    private List<Double> results(double x, double y) {
        List<Double> values = new ArrayList<>();
        values.add(x + y);
        values.add(x - y);
        values.add(x * y);
        if (Math.abs(y) > EPS) {
            values.add(x / y);
        }
        return values;
    }
}

import java.util.*;

class Solution {
    private static final double TARGET = 24.0;
    private static final double EPS = 1e-6;

    public boolean judgePoint24(int[] cards) {
        int n = cards.length;
        List<Double>[] possible = new ArrayList[1 << n];
        for (int mask = 0; mask < possible.length; mask++) {
            possible[mask] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            possible[1 << i].add((double) cards[i]);
        }

        for (int mask = 1; mask < (1 << n); mask++) {
            if ((mask & (mask - 1)) == 0) {
                continue;
            }
            for (int left = (mask - 1) & mask; left > 0; left = (left - 1) & mask) {
                int right = mask ^ left;
                if (left > right) {
                    continue;
                }
                for (double a : possible[left]) {
                    for (double b : possible[right]) {
                        addCombinations(possible[mask], a, b);
                    }
                }
            }
        }

        for (double value : possible[(1 << n) - 1]) {
            if (Math.abs(value - TARGET) < EPS) {
                return true;
            }
        }
        return false;
    }

    private void addCombinations(List<Double> values, double a, double b) {
        values.add(a + b);
        values.add(a - b);
        values.add(b - a);
        values.add(a * b);
        if (Math.abs(b) > EPS) {
            values.add(a / b);
        }
        if (Math.abs(a) > EPS) {
            values.add(b / a);
        }
    }
}

