class Solution {
    public boolean judgePoint24(int[] cards) {
        List<Fraction> values = new ArrayList<>();
        for (int card : cards) {
            values.add(new Fraction(card, 1));
        }
        return search(values);
    }

    private boolean search(List<Fraction> values) {
        if (values.size() == 1) {
            Fraction value = values.get(0);
            return value.num == 24L * value.den;
        }
        int n = values.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                List<Fraction> rest = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        rest.add(values.get(k));
                    }
                }
                Fraction a = values.get(i);
                Fraction b = values.get(j);
                for (Fraction next : rationalCandidates(a, b)) {
                    rest.add(next);
                    if (search(rest)) {
                        return true;
                    }
                    rest.remove(rest.size() - 1);
                }
            }
        }
        return false;
    }

    private List<Fraction> rationalCandidates(Fraction a, Fraction b) {
        List<Fraction> candidates = new ArrayList<>();
        candidates.add(a.add(b));
        candidates.add(a.subtract(b));
        candidates.add(b.subtract(a));
        candidates.add(a.multiply(b));
        if (!b.isZero()) {
            candidates.add(a.divide(b));
        }
        if (!a.isZero()) {
            candidates.add(b.divide(a));
        }
        return candidates;
    }

    private static final class Fraction {
        private final long num;
        private final long den;

        Fraction(long num, long den) {
            if (den < 0) {
                num = -num;
                den = -den;
            }
            long g = gcd(Math.abs(num), den);
            this.num = num / g;
            this.den = den / g;
        }

        boolean isZero() {
            return num == 0;
        }

        Fraction add(Fraction other) {
            return new Fraction(num * other.den + other.num * den, den * other.den);
        }

        Fraction subtract(Fraction other) {
            return new Fraction(num * other.den - other.num * den, den * other.den);
        }

        Fraction multiply(Fraction other) {
            return new Fraction(num * other.num, den * other.den);
        }

        Fraction divide(Fraction other) {
            return new Fraction(num * other.den, den * other.num);
        }

        private static long gcd(long a, long b) {
            while (b != 0) {
                long t = a % b;
                a = b;
                b = t;
            }
            return a == 0 ? 1 : a;
        }
    }
}

import java.util.*;

class Solution {
    private static final double TARGET = 24.0;
    private static final double EPS = 1e-6;

    public boolean judgePoint24(int[] cards) {
        List<Double> values = new ArrayList<>();
        for (int card : cards) {
            values.add((double) card);
        }
        return search(values, new HashMap<>());
    }

    private boolean search(List<Double> values, Map<String, Boolean> memo) {
        if (values.size() == 1) {
            return Math.abs(values.get(0) - TARGET) < EPS;
        }
        String key = canonicalKey(values);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int n = values.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                List<Double> nextValues = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        nextValues.add(values.get(k));
                    }
                }
                double a = values.get(i);
                double b = values.get(j);
                for (double next : nextResults(a, b)) {
                    nextValues.add(next);
                    if (search(nextValues, memo)) {
                        memo.put(key, true);
                        return true;
                    }
                    nextValues.remove(nextValues.size() - 1);
                }
            }
        }
        memo.put(key, false);
        return false;
    }

    private String canonicalKey(List<Double> values) {
        List<Long> rounded = new ArrayList<>();
        for (double value : values) {
            rounded.add(Math.round(value * 1_000_000));
        }
        Collections.sort(rounded);
        return rounded.toString();
    }

    private List<Double> nextResults(double a, double b) {
        List<Double> results = new ArrayList<>();
        results.add(a + b);
        results.add(a - b);
        results.add(b - a);
        results.add(a * b);
        if (Math.abs(b) > EPS) {
            results.add(a / b);
        }
        if (Math.abs(a) > EPS) {
            results.add(b / a);
        }
        return results;
    }
}
